    name: "Toledo Power Wash",
    description:
      "Commercial and residential power washing and soft washing serving Toledo and Northwest Ohio.",
    url: siteUrl,
    image: `${siteUrl}/og.png`,
    telephone: telephone || undefined,
    email: biz.email,
    priceRange: "$$",
    address: {
      "@type": "PostalAddress",
      addressLocality: "Toledo",
      addressRegion: "OH",
      addressCountry: "US",
    },
    geo: {
      "@type": "GeoCoordinates",
      latitude: 41.6528,
      longitude: -83.5379,
    },
    areaServed: [
      { "@type": "City", name: "Toledo" },
      { "@type": "AdministrativeArea", name: "Lucas County" },
      { "@type": "AdministrativeArea", name: "Northwest Ohio" },
    ],
    founder: {
      "@type": "Person",
      name: "Austin Stickley",
    },
    openingHoursSpecification: [
      {
        "@type": "OpeningHoursSpecification",
        dayOfWeek: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"],
        opens: "07:00",
        closes: "19:00",
      },
    ],
    knowsAbout: [
      "Power washing",
      "Pressure washing",
      "Soft washing",
