@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: dark;
}

html {
  scroll-behavior: smooth;
}

body {
  @apply bg-ink text-slate-100 antialiased;
  background-image:
    radial-gradient(900px 500px at 10% -10%, rgba(59, 130, 246, 0.16), transparent 55%),
    radial-gradient(700px 400px at 100% 0%, rgba(30, 58, 95, 0.45), transparent 50%),
    linear-gradient(180deg, #0b1220 0%, #0a1018 100%);
  min-height: 100vh;
}

::selection {
  @apply bg-sky/40 text-white;
}

.container-page {
  @apply mx-auto w-full max-w-6xl px-5 sm:px-6 lg:px-8;
}

.card {
